// 左エンコーダーのプッシュ（マトリクス [0,0]）はキーマップで KC_AUDIO_MUTE を割り当てています
// （ogm9-Izanami の GP29 ダイレクトピン処理は不要なので削除）

// ---- Dynamic Macro トリガー（キーの割り当てではなく、物理的なキー位置で判定）----
// [Ctrlの位置] + [Shiftの位置] + [@の位置] を押したまま（いずれもレイヤー0基準の物理位置）
//   [Mの位置] -> DM_REC1（記録開始）
//   [Lの位置] -> DM_PLY1（再生）
//   [Pの位置] -> DM_RSTP（記録停止）
#define DM_POS_CTL_ROW  3   // Ctrl の位置 : matrix [3,0]
#define DM_POS_CTL_COL  0
#define DM_POS_SFT_ROW  2   // Shift の位置: matrix [2,0]
#define DM_POS_SFT_COL  0
#define DM_POS_AT_ROW   2   // @ の位置 : matrix [2,11]
#define DM_POS_AT_COL  11
#define DM_POS_REC_ROW  2   // M の位置   : matrix [2,7]
#define DM_POS_REC_COL  7
#define DM_POS_PLY_ROW  1   // L の位置   : matrix [1,9]
#define DM_POS_PLY_COL  9
#define DM_POS_STP_ROW  0   // P の位置 : matrix [0,10]
#define DM_POS_STP_COL  10

static bool     dm_trigger_active  = false;  // トリガー中のキー（押してから離すまで）
static keypos_t dm_trigger_pos;
static uint16_t dm_trigger_kc      = KC_NO;  // 実行する DM_* キーコード
static bool     dm_in_playback     = false;  // マクロ再生中はトリガー判定をしない

// マクロ再生中に Alt(Mac は Cmd)+Tab でウインドウを切り替えたら、Alt/Cmd を離した後に少し待つ
// （切り替え先のウインドウが前面に来る前に、続きのキーが送られてしまうのを防ぐ）
#define DM_ALT_TAB_DELAY_MS 300
static bool dm_alt_tab_pending = false;

// Ctrl / Shift / @ の位置のキーが「今まさに物理的に」押されているか
// （イベントで追いかけると、マクロ再生で離しイベントが流れて状態がずれるため、マトリクスを直接見る）
static bool dm_trigger_mods_held(void) {
    return matrix_is_on(DM_POS_CTL_ROW, DM_POS_CTL_COL) &&
           matrix_is_on(DM_POS_SFT_ROW, DM_POS_SFT_COL) &&
           matrix_is_on(DM_POS_AT_ROW,  DM_POS_AT_COL);
}

static bool dm_is_pos(keyrecord_t *record, uint8_t row, uint8_t col) {
    return record->event.key.row == row && record->event.key.col == col;
}

// ---- Mac 接続時（デフォルトレイヤー3）だけ Alt+Tab を Cmd+Tab に置き換える ----
// Alt を押したまま Tab を押すと、Alt を Cmd に持ち替えて Tab を送る。
// Alt を離すまで Cmd を押しっぱなしにするので、Tab を続けて押してアプリを選べる（Shift で逆順）。
// 接続先OSで決まるデフォルトレイヤー（Mac = 3、それ以外 = 0）。housekeeping_task_user で設定
static uint8_t os_default_layer = 0;

static bool mac_cmd_tab_active = false;

static bool mac_cmd_tab_process(uint16_t keycode, keyrecord_t *record) {
    if (keycode == KC_TAB && record->event.pressed &&
        os_default_layer == 3 &&
        (mac_cmd_tab_active || (get_mods() & MOD_MASK_ALT))) {
        if (!mac_cmd_tab_active) {
            del_mods(MOD_MASK_ALT);
            register_mods(MOD_BIT(KC_LGUI));
            mac_cmd_tab_active = true;
        }
        return true; // Tab 自体は通常どおり送る
    }
    if (mac_cmd_tab_active && !record->event.pressed &&
        (keycode == KC_LEFT_ALT || keycode == KC_RIGHT_ALT)) {
        unregister_mods(MOD_BIT(KC_LGUI));
        mac_cmd_tab_active = false;
    }
    return true;
}

// ---- 左上キー（左エンコーダー押し込み / LAYER_STATUS）長押し中のレイヤー固定 ----
// デフォルトレイヤーにいるとき: 長押ししながら Q,W,E,R,T,Y,U,P の位置 -> レイヤー 1,2,3,4,5,6,7,0 に固定
// 固定中（デフォルトレイヤー以外）: 長押ししながら どのキーを押しても デフォルトレイヤーに戻す
// （キーの割り当てではなく物理的なキー位置で判定。長押し中に押したキーは PC に送らない）
static bool layer_key_held = false;
static bool layer_key_used = false;

static int8_t layer_lock_target(keypos_t key) {
    if (key.row != 0) return -1;
    if (key.col >= 1 && key.col <= 7) return key.col; // Q W E R T Y U -> 1〜7
    if (key.col == 10) return 0;                      // P -> 0
    return -1;
}

static bool layer_is_default(void) {
    return layer_state == 0 && get_highest_layer(default_layer_state) == os_default_layer;
}

static void layer_lock(uint8_t layer) {
    layer_clear();
    if (layer >= os_default_layer) {
        // デフォルトレイヤーの上に重ねる（透過キーはデフォルトレイヤーのキーになる）
        default_layer_set(1UL << os_default_layer);
        if (layer != os_default_layer) layer_on(layer);
    } else {
        // Mac 接続時にレイヤー0〜2を選んだ場合: レイヤー0を土台にする（透過キーはレイヤー0のキーになる）
        default_layer_set(1UL << 0);
        if (layer != 0) layer_on(layer);
    }
}

static void layer_unlock(void) {
    layer_clear();
    default_layer_set(1UL << os_default_layer);
}

// true を返したらそのキーは処理済み（PC に送らない）
static bool layer_key_combo_process(uint16_t keycode, keyrecord_t *record) {
    if (!layer_key_held || keycode == LAYER_STATUS || !record->event.pressed) return false;
    layer_key_used = true;
    if (layer_is_default()) {
        int8_t target = layer_lock_target(record->event.key);
        if (target >= 0) layer_lock((uint8_t)target);
    } else {
        layer_unlock();
    }
    return true;
}

// ---- AUTO_CLICK: 押している間、左クリックを連打する ----
// 1 秒あたりの回数は押したキーで決まる: AUTO_CLICK = 20 回, AUTO_CLICK_5 / _10 / _30 / _50 / _100 / _200 / _500 = 5 / 10 / 30 / 50 / 100 / 200 / 500 回
// 押した瞬間を起点に、n 回目の押す/離すの切り替えを n * 500 / 回数 (ms) 後に行う。
// 切り替えのたびに起点を取り直さないので、端数（30 回なら 16.67ms）や処理の遅れが積み重ならず、平均がちょうどその回数になる
static uint16_t auto_click_rate_for(uint16_t keycode) {
    switch (keycode) {
        case AUTO_CLICK_5:  return 5;
        case AUTO_CLICK_10: return 10;
        case AUTO_CLICK_30: return 30;
        case AUTO_CLICK_50: return 50;
        case AUTO_CLICK_100: return 100;
        case AUTO_CLICK_200: return 200;
        case AUTO_CLICK_500: return 500;   // 1ms ごとに押す/離すを切り替える（USB の送信間隔 1ms が上限）
        default:            return 20;   // AUTO_CLICK
    }
}
static uint16_t auto_click_rate  = 20;
static bool     auto_click_held  = false;
static bool     auto_click_down  = false;
static uint32_t auto_click_start = 0;
static uint32_t auto_click_steps = 0;

static void auto_click_task(void) {
    if (!auto_click_held) return;
    if (timer_elapsed32(auto_click_start) < auto_click_steps * 500 / auto_click_rate) return;
    auto_click_steps++;
    if (auto_click_down) {
        unregister_code(KC_MS_BTN1);
    } else {
        register_code(KC_MS_BTN1);
    }
    auto_click_down = !auto_click_down;
}

// ---- 左ノブ押し込み + 右下キー（物理位置 [3,11]、レイヤー0 では →）で設定ツールを Chrome で開く ----
// Mac: Spotlight で Google Chrome を起動 → 新しいタブ → URL を入力
// Windows など: Win+R（ファイル名を指定して実行）に「chrome <URL>」を入力
#define CONFIG_TOOL_URL "https://oogamizin.github.io/KeyBord.ogm10-Jupiter/"
#define OPEN_TOOL_POS_ROW 3
#define OPEN_TOOL_POS_COL 11

static void open_config_tool(void) {
    clear_mods();
    clear_oneshot_mods();
    tap_code(KC_LANGUAGE_2);              // 英数（IME オフ）
    wait_ms(50);
    if (os_default_layer == 3) {
        tap_code16(LGUI(KC_SPACE));       // Spotlight
        wait_ms(400);
        SEND_STRING("Google Chrome");
        wait_ms(400);
        tap_code(KC_ENTER);
        wait_ms(1500);                    // Chrome が前面に来るまで
        tap_code16(LGUI(KC_T));           // 新しいタブ
        wait_ms(300);
        SEND_STRING(CONFIG_TOOL_URL);
    } else {
        tap_code16(LGUI(KC_R));           // ファイル名を指定して実行
        wait_ms(500);
        SEND_STRING("chrome " CONFIG_TOOL_URL);
    }
    tap_code(KC_ENTER);
}
// ---- DM_PLY1 / DM_PLY2 キーを「Ctrl・Shift・@ + L」と同じ動きにそろえる ----
//   押したとき: 記録中なら記録を止める（記録していなければ何もしない）
//   離したとき: 再生する。再生中は dm_in_playback を立てるので、Alt(Cmd)+Tab のあとの待ちも入る
// Dynamic Macro の処理は process_record_user より先に動くので、その前の段階（pre_process）で横取りする
bool pre_process_record_user(uint16_t keycode, keyrecord_t *record) {
    if (!dm_in_playback && (keycode == DM_PLY1 || keycode == DM_PLY2)) {
        if (record->event.pressed) {
            process_dynamic_macro(DM_RSTP, record);   // 記録中なら停止
        } else {
            dm_alt_tab_pending = false;
            dm_in_playback     = true;
            process_dynamic_macro(keycode, record);   // 離したときに再生
            dm_in_playback     = false;
            dm_alt_tab_pending = false;
        }
        return false;                                 // PC には送らない
    }
    return true;
}

bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    // 左ノブ押し込み + 右ノブ押し込み + Backspace（いずれも物理位置: [0,0] [0,11] [1,11]）の3つ同時押しで
    // ブートローダー（QK_BOOT）に入る。マトリクスを直接見るので、レイヤーやキー割り当てに関係なく動く
    if (record->event.pressed &&
        matrix_is_on(0, 0) && matrix_is_on(0, 11) && matrix_is_on(1, 11)) {
        reset_keyboard();
        return false;
    }
    // 左ノブを押したまま右下キー → 設定ツールを開く（左ノブの単押し動作・レイヤー固定は行わない）
    if (record->event.pressed && matrix_is_on(0, 0) &&
        record->event.key.row == OPEN_TOOL_POS_ROW && record->event.key.col == OPEN_TOOL_POS_COL) {
        layer_key_used = true;
        open_config_tool();
        return false;
    }
    if (layer_key_combo_process(keycode, record)) return false;

    // マクロ再生中: Alt/Cmd を押したまま Tab が押されたら覚えておく（待つのは post_process_record_user）
    if (dm_in_playback && keycode == KC_TAB && record->event.pressed &&
        (get_mods() & (MOD_MASK_ALT | MOD_MASK_GUI))) {
        dm_alt_tab_pending = true;
    }
    mac_cmd_tab_process(keycode, record);

    if (!dm_in_playback) {
        if (record->event.pressed) {
            if (dm_trigger_mods_held()) {
                uint16_t dm = KC_NO;
                if (dm_is_pos(record, DM_POS_REC_ROW, DM_POS_REC_COL)) {
                    dm = DM_REC1;
                } else if (dm_is_pos(record, DM_POS_PLY_ROW, DM_POS_PLY_COL)) {
                    dm = DM_PLY1;
                } else if (dm_is_pos(record, DM_POS_STP_ROW, DM_POS_STP_COL)) {
                    dm = DM_RSTP;
                }
                if (dm != KC_NO) {
                    dm_trigger_active = true;
                    dm_trigger_pos    = record->event.key;
                    dm_trigger_kc     = dm;
                    if (dm == DM_PLY1) {
                        // 記録中なら先に停止してから再生する（サクラエディタと同じ挙動）
                        // 記録中でなければ何も起きない
                        process_dynamic_macro(DM_RSTP, record);
                    }
                    process_dynamic_macro(dm, record);  // RSTP は押したときに動く
                    return false;                       // PCには送らない
                }
            }
        } else if (dm_trigger_active && KEYEQ(record->event.key, dm_trigger_pos)) {
            uint16_t kc       = dm_trigger_kc;
            dm_trigger_active = false;
            dm_trigger_kc     = KC_NO;
            dm_in_playback    = (kc == DM_PLY1);
            process_dynamic_macro(kc, record);          // REC / PLY は離したときに動く
            dm_in_playback    = false;
            dm_alt_tab_pending = false;
            return false;                               // 離しもPCには送らない
        }
    }

    switch (keycode) {
        case AUTO_CLICK:
        case AUTO_CLICK_5:
        case AUTO_CLICK_10:
        case AUTO_CLICK_30:
        case AUTO_CLICK_50:
        case AUTO_CLICK_100:
        case AUTO_CLICK_200:
        case AUTO_CLICK_500:
            auto_click_held = record->event.pressed;
            if (record->event.pressed) {
                auto_click_rate  = auto_click_rate_for(keycode);
                auto_click_down  = false;
                auto_click_start = timer_read32();
                auto_click_steps = 0;                                  // 0 回目（押した瞬間）にすぐ 1 回目を押す
            } else if (auto_click_down) {
                unregister_code(KC_MS_BTN1);
                auto_click_down = false;
            }
            return false;

        case SQL_SELECT_TMP:
            if (record->event.pressed) {
                // 英数(IMEオフ)に切り替えてからSQLのひな形を入力
                tap_code(KC_LANGUAGE_2);
                wait_ms(50);
                SEND_STRING("Select *\nFrom \nWhere 1=1\nOrder by 1");
                // 2行上(From の行)に戻って行末へ移動
                tap_code(KC_UP);
                tap_code(KC_UP);
                if (os_default_layer == 3) {
                    tap_code16(LGUI(KC_RIGHT));  // Mac: Cmd+→
                } else {
                    tap_code(KC_END);            // Windows など: End
                }
            }
            return false;

        case LAYER_STATUS:
            if (record->event.pressed) {
                layer_key_held = true;
                layer_key_used = false;
            } else {
                layer_key_held = false;
                if (!layer_key_used) {
                    // 単押し: 現在有効なレイヤーとデフォルトレイヤーを入力する（例: "Layer 4 (default 3: macOS)"）
                    uint8_t cur = get_highest_layer(layer_state | default_layer_state);
                    // 英数(IMEオフ)に切り替えてから入力
                    tap_code(KC_LANGUAGE_2);
                    wait_ms(50);
                    SEND_STRING("Layer ");
                    send_char('0' + cur);
                    SEND_STRING(" (default ");
                    send_char('0' + os_default_layer);
                    if (os_default_layer == 3) {
                        SEND_STRING(": macOS)");
                    } else {
                        SEND_STRING(": Windows)");
                    }
                }
            }
            return false;

        case LAYER_INFO:
            if (record->event.pressed) {
                // 現在のデフォルトレイヤーに応じた文章を入力する
                if (os_default_layer == 3) {
                    SEND_STRING("The default layer is 3 for macOS.");
                } else {
                    SEND_STRING("The default layer is 0 for Windows and other operating systems.");
                }
            }
            return false;

        case MAC_SCREENSHOT:
            if (record->event.pressed) {
                // Shift + Command + Control を押す
                register_code(KC_LSFT);
                register_code(KC_LGUI);
                register_code(KC_LCTL);

                wait_ms(10);

                // 4を押して離す
                tap_code(KC_4);

                // 修飾キーを離す
                unregister_code(KC_LCTL);
                unregister_code(KC_LGUI);
                unregister_code(KC_LSFT);
            }
            return false;
    }

    return true;
}

// マクロ再生中の Alt(Cmd)+Tab: Alt/Cmd を離した（＝ウインドウが切り替わった）後に DM_ALT_TAB_DELAY_MS 待つ
// （離すキーが PC に送られた後に呼ばれる）
void post_process_record_user(uint16_t keycode, keyrecord_t *record) {
    if (dm_alt_tab_pending && !record->event.pressed &&
        (keycode == KC_LEFT_ALT || keycode == KC_RIGHT_ALT ||
         keycode == KC_LEFT_GUI || keycode == KC_RIGHT_GUI)) {
        dm_alt_tab_pending = false;
        wait_ms(DM_ALT_TAB_DELAY_MS);
    }
}

// ---- 設定ツール（docs/index.html）のレイヤー表示向け: 現在のレイヤー状態を Raw HID で知らせる ----
// VIA / Vial が使っていない先頭バイト 0xF7 を、このキーボード専用のコマンドとして使う。
//   PC -> キーボード: [0xF7, 0x01]            現在の状態を返す。同時に、以後 3 秒間の「変化通知」を申し込む
//   キーボード -> PC: [0xF7, 0x01, 1, 最上位レイヤー, layer_state(4バイト LE), default_layer_state(4バイト LE), OS別デフォルトレイヤー]
//   キーボード -> PC: [0xF7, 0x02, ...同じ内容]  申し込み中にレイヤーが変わったとき、キーボード側から送る通知
// 表示ツールは 1 秒ごとに問い合わせ直すので、ツールを閉じれば 3 秒で通知は止まる（標準の Vial には影響しない）
//
// キー1個単位で「初期設定に戻す」ための問い合わせ（書き込みはしない。読むだけ）
//   PC -> キーボード: [0xF7, 0x03, 位置(上位), 位置(下位)]  位置 = (レイヤー * MATRIX_ROWS + 行) * MATRIX_COLS + 列
//   キーボード -> PC: [0xF7, 0x03, 位置(上位), 位置(下位), その位置から 14 キーぶんの初期キーコード（各 2 バイト、上位が先）]
//   PC -> キーボード: [0xF7, 0x04, レイヤー, エンコーダー番号]
//   キーボード -> PC: [0xF7, 0x04, レイヤー, エンコーダー番号, 反時計回り(2 バイト), 時計回り(2 バイト)]
//   PC -> キーボード: [0xF7, 0x05]
//   キーボード -> PC: [0xF7, 0x05, ビルド日時の文字列（例 "Nov 18 2026 07:05:00"、0 終端）]
//   ※ 設定ツールはこの文字列と、GitHub Pages に公開した最新版（docs/firmware/latest.json）を比べて更新の有無を出す。
//     公開する側（.github/scripts/publish_fw.py）は、.uf2 の中の "JUPFW:" に続く文字列を同じ版として読み取る。
//   PC -> キーボード: [0xF7, 0x06, 位置(上位), 位置(下位)]
//   キーボード -> PC: [0xF7, 0x06, 位置(上位), 位置(下位), 全体の長さ(上位), 全体の長さ(下位), その位置から 26 バイトぶんの default_macro_buffer]
//   ※ 設定ツールのマクロ画面の「初期状態に戻す」で使う（読むだけ。書き込みは設定ツールの「書込」で行う）
#define JUP_HID_ID            0xF7
#define JUP_HID_GET           0x01
#define JUP_HID_PUSH          0x02
#define JUP_HID_DEFAULT_KEYS  0x03
#define JUP_HID_DEFAULT_ENC   0x04
#define JUP_HID_FW_BUILD      0x05
#define JUP_HID_DEFAULT_MACRO 0x06
#define JUP_HID_VERSION       1
#define JUP_HID_SUBSCRIBE_MS  3000

// ファームウェアの版（ビルド日時）。先頭の "JUPFW:" は .uf2 から版を探すための目印
static const char jup_fw_build[] = "JUPFW:" __DATE__ " " __TIME__;

static bool     jup_hid_subscribed   = false;
static uint32_t jup_hid_sub_timer    = 0;
static uint32_t jup_hid_sent_layer   = 0;
static uint32_t jup_hid_sent_default = 0;

static void jup_hid_fill(uint8_t *data, uint8_t kind) {
    uint32_t ls = (uint32_t)layer_state;
    uint32_t ds = (uint32_t)default_layer_state;
    data[0]  = JUP_HID_ID;
    data[1]  = kind;
    data[2]  = JUP_HID_VERSION;
    data[3]  = get_highest_layer(layer_state | default_layer_state);
    data[4]  = ls & 0xFF;
    data[5]  = (ls >> 8) & 0xFF;
    data[6]  = (ls >> 16) & 0xFF;
    data[7]  = (ls >> 24) & 0xFF;
    data[8]  = ds & 0xFF;
    data[9]  = (ds >> 8) & 0xFF;
    data[10] = (ds >> 16) & 0xFF;
    data[11] = (ds >> 24) & 0xFF;
    data[12] = os_default_layer;
    jup_hid_sent_layer   = ls;
    jup_hid_sent_default = ds;
}

// VIA / Vial が知らないコマンドはここに回ってくる（返事は呼び出し元が送るので、ここでは raw_hid_send しない）
void raw_hid_receive_kb(uint8_t *data, uint8_t length) {
    if (length >= 13 && data[0] == JUP_HID_ID && data[1] == JUP_HID_GET) {
        jup_hid_fill(data, JUP_HID_GET);
        jup_hid_subscribed = true;
        jup_hid_sub_timer  = timer_read32();
        return;
    }
    if (length >= 32 && data[0] == JUP_HID_ID && data[1] == JUP_HID_DEFAULT_KEYS) {
        const uint16_t total = (uint16_t)DYNAMIC_KEYMAP_LAYER_COUNT * MATRIX_ROWS * MATRIX_COLS;
        uint16_t pos = ((uint16_t)data[2] << 8) | data[3];
        for (uint8_t i = 0; i < 14; i++, pos++) {
            uint16_t kc = 0;
            if (pos < total) {
                uint8_t layer = pos / (MATRIX_ROWS * MATRIX_COLS);
                uint8_t rc    = pos % (MATRIX_ROWS * MATRIX_COLS);
                kc = keycode_at_keymap_location_raw(layer, rc / MATRIX_COLS, rc % MATRIX_COLS);
            }
            data[4 + i * 2] = kc >> 8;
            data[5 + i * 2] = kc & 0xFF;
        }
        return;
    }
    if (length >= 32 && data[0] == JUP_HID_ID && data[1] == JUP_HID_DEFAULT_MACRO) {
        const uint16_t total = sizeof(default_macro_buffer);
        uint16_t       off   = ((uint16_t)data[2] << 8) | data[3];
        data[4] = total >> 8;
        data[5] = total & 0xFF;
        for (uint8_t i = 0; i < 26; i++, off++) data[6 + i] = off < total ? pgm_read_byte(&default_macro_buffer[off]) : 0;
        return;
    }
    if (length >= 32 && data[0] == JUP_HID_ID && data[1] == JUP_HID_FW_BUILD) {
        const char *v = jup_fw_build + 6;  // "JUPFW:" を飛ばす
        uint8_t i = 0;
        for (; v[i] && i < 29; i++) data[2 + i] = (uint8_t)v[i];
        for (; i < 30; i++) data[2 + i] = 0;
        return;
    }
#ifdef ENCODER_MAP_ENABLE
    if (length >= 8 && data[0] == JUP_HID_ID && data[1] == JUP_HID_DEFAULT_ENC) {
        uint16_t ccw = 0, cw = 0;
        if (data[2] < DYNAMIC_KEYMAP_LAYER_COUNT && data[3] < NUM_ENCODERS) {
            ccw = keycode_at_encodermap_location_raw(data[2], data[3], false);
            cw  = keycode_at_encodermap_location_raw(data[2], data[3], true);
        }
        data[4] = ccw >> 8; data[5] = ccw & 0xFF;
        data[6] = cw >> 8;  data[7] = cw & 0xFF;
        return;
    }
#endif
    data[0] = 0xFF; // id_unhandled（未対応コマンド）
}

// 申し込み中にレイヤーが変わったら通知する（housekeeping_task_user から毎周呼ぶ）
static void jup_hid_task(void) {
    if (!jup_hid_subscribed) return;
    if (timer_elapsed32(jup_hid_sub_timer) > JUP_HID_SUBSCRIBE_MS) {
        jup_hid_subscribed = false;
        return;
    }
    if ((uint32_t)layer_state != jup_hid_sent_layer || (uint32_t)default_layer_state != jup_hid_sent_default) {
        uint8_t buf[32] = {0};
        jup_hid_fill(buf, JUP_HID_PUSH);
        raw_hid_send(buf, sizeof(buf));
    }
}

// ---- Vial のロック解除を早くする ----
// Vial 本体の解除は 50 回の確認（1 回 0.1 秒以上）が必要で 5〜10 秒かかる。
// 解除の確認中に Q と P の位置（VIAL_UNLOCK_COMBO と同じ）を FAST_UNLOCK_MS 押し続けたら、その時点で解除済みにする。
// Vial の画面は次の問い合わせで「解除済み」を受け取って閉じる
extern int vial_unlocked;
extern int vial_unlock_in_progress;
#define FAST_UNLOCK_MS 1000
static bool     fast_unlock_holding = false;
static uint16_t fast_unlock_timer = 0;

static void fast_unlock_task(void) {
    if (!vial_unlock_in_progress || !(matrix_is_on(0, 1) && matrix_is_on(0, 10))) {
        fast_unlock_holding = false;
        return;
    }
    if (!fast_unlock_holding) {
        fast_unlock_holding = true;
        fast_unlock_timer = timer_read();
    } else if (timer_elapsed(fast_unlock_timer) >= FAST_UNLOCK_MS) {
        vial_unlocked = 1;
        vial_unlock_in_progress = 0;
        fast_unlock_holding = false;
    }
}

// 接続先OSに応じてデフォルトレイヤーを切り替える
// Mac(macOS / iOS) -> レイヤー3、それ以外 -> レイヤー0
void housekeeping_task_user(void) {
    static os_variant_t applied_os = OS_UNSURE;
    os_variant_t os = detected_host_os();
    if (os != applied_os) {
        applied_os = os;
        if (os == OS_MACOS || os == OS_IOS) {
            os_default_layer = 3;
            layer_clear();
            default_layer_set(1UL << 3);
        } else {
            os_default_layer = 0;
            layer_clear();
            default_layer_set(1UL << 0);
        }
    }
    auto_click_task();
    fast_unlock_task();
    jup_hid_task();
}

